import { mkdir, readdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import ts from "typescript";
import {
	COLLECTIONS,
	GLOBALS,
	SYSTEM_COLLECTIONS,
} from "../src/config/content.ts";
import { JOBS } from "../src/config/jobs.ts";
import { PAYLOAD_TYPE_PATHS } from "./lib/payload-type-paths.mjs";

const GENERATED_SOURCE = PAYLOAD_TYPE_PATHS.source;
const OUTPUT_DIRECTORY = PAYLOAD_TYPE_PATHS.output;
const OLD_OUTPUT = PAYLOAD_TYPE_PATHS.obsolete;
const HEADER =
	"// Generated by pnpm payload:types. Edit the CMS schemas, not this file.\n";
const MODULE_NAME = "payload";
const BLOCKS_FIELD = "blocks";
const BLOCK_TYPE_NAME = "ContentBlock";
const PUBLIC_PAYLOAD_TYPES = new Set([
	"Media",
	"Page",
	"PayloadJob",
	"Product",
	"Project",
	"Service",
	"SiteSetting",
]);
const KEY_GROUPS = { COLLECTIONS, GLOBALS, SYSTEM_COLLECTIONS, JOBS };
const source = ts.createSourceFile(
	GENERATED_SOURCE,
	await readFile(GENERATED_SOURCE, "utf8"),
	ts.ScriptTarget.Latest,
	true,
);
const declarations = source.statements.filter(
	(statement) =>
		ts.isInterfaceDeclaration(statement) ||
		ts.isTypeAliasDeclaration(statement),
);
const printer = ts.createPrinter({ newLine: ts.NewLineKind.LineFeed });
const sharedBlocks = findSharedBlocks(declarations);
const typeNames = new Set(
	declarations
		.map((declaration) => declaration.name.text)
		.concat(sharedBlocks ? [BLOCK_TYPE_NAME] : []),
);
function findSharedBlocks(items) {
	const groups = new Map();
	for (const declaration of items) {
		if (!ts.isInterfaceDeclaration(declaration)) {
			continue;
		}
		const property = declaration.members.find(
			(member) =>
				ts.isPropertySignature(member) &&
				ts.isIdentifier(member.name) &&
				member.name.text === BLOCKS_FIELD &&
				member.type &&
				ts.isUnionTypeNode(member.type),
		);
		const array = property?.type.types.find(ts.isArrayTypeNode);
		if (!array || !ts.isParenthesizedTypeNode(array.elementType)) {
			continue;
		}
		const key = printer.printNode(
			ts.EmitHint.Unspecified,
			array.elementType.type,
			source,
		);
		const group = groups.get(key) ?? {
			element: array.elementType.type,
			names: [],
		};
		group.names.push(declaration.name.text);
		groups.set(key, group);
	}
	const matches = [...groups.values()].filter(
		(group) => group.names.length > 1,
	);
	if (matches.length > 1) {
		throw new Error("Multiple shared content-block types need explicit names");
	}
	return matches[0];
}

function transformDeclaration(declaration) {
	const constants = new Map();
	const transformed = ts.transform(declaration, [
		(context) => {
			function visit(node) {
				if (
					sharedBlocks?.names.includes(declaration.name.text) &&
					ts.isPropertySignature(node) &&
					ts.isIdentifier(node.name) &&
					node.name.text === BLOCKS_FIELD
				) {
					const contentBlocks = ts.factory.createArrayTypeNode(
						ts.factory.createTypeReferenceNode(BLOCK_TYPE_NAME),
					);
					const nullableBlocks = ts.factory.createUnionTypeNode([
						contentBlocks,
						ts.factory.createLiteralTypeNode(ts.factory.createNull()),
					]);
					return ts.factory.updatePropertySignature(
						node,
						node.modifiers,
						node.name,
						node.questionToken,
						nullableBlocks,
					);
				}
				if (node.kind === ts.SyntaxKind.AnyKeyword) {
					return ts.factory.createKeywordTypeNode(ts.SyntaxKind.UnknownKeyword);
				}
				if (ts.isTypeLiteralNode(node) && node.members.length === 0) {
					return ts.factory.createTypeReferenceNode("Record", [
						ts.factory.createKeywordTypeNode(ts.SyntaxKind.NeverKeyword),
						ts.factory.createKeywordTypeNode(ts.SyntaxKind.NeverKeyword),
					]);
				}
				if (
					declaration.name.text === "Config" &&
					ts.isPropertySignature(node)
				) {
					const name =
						ts.isIdentifier(node.name) || ts.isStringLiteral(node.name)
							? node.name.text
							: undefined;
					for (const [group, values] of Object.entries(KEY_GROUPS)) {
						const entry = Object.entries(values).find(
							([, value]) => value === name,
						);
						if (entry) {
							constants.set(group, group === "JOBS" ? "jobs" : "content");
							return ts.factory.updatePropertySignature(
								node,
								node.modifiers,
								ts.factory.createComputedPropertyName(
									ts.factory.createPropertyAccessExpression(
										ts.factory.createIdentifier(group),
										entry[0],
									),
								),
								node.questionToken,
								ts.visitNode(node.type, visit),
							);
						}
					}
				}
				return ts.visitEachChild(node, visit, context);
			}
			return visit;
		},
	]);
	const text = printer.printNode(
		ts.EmitHint.Unspecified,
		transformed.transformed[0],
		source,
	);
	const node = transformed.transformed[0];
	transformed.dispose();
	return { text, constants, node };
}

function referencedTypes(declaration) {
	const names = new Set();
	function visit(node) {
		if (ts.isTypeReferenceNode(node) && ts.isIdentifier(node.typeName)) {
			const name = node.typeName.text;
			if (typeNames.has(name) && name !== declaration.name.text) {
				names.add(name);
			}
		}
		ts.forEachChild(node, visit);
	}
	visit(declaration);
	return [...names].sort();
}

await mkdir(OUTPUT_DIRECTORY, { recursive: true });
const expectedFiles = new Set([
	...declarations.map((declaration) => `${declaration.name.text}.ts`),
	...(sharedBlocks ? [`${BLOCK_TYPE_NAME}.ts`] : []),
	"index.ts",
	"payload.d.ts",
]);
for (const file of await readdir(OUTPUT_DIRECTORY)) {
	if (!expectedFiles.has(file)) {
		const filename = path.join(OUTPUT_DIRECTORY, file);
		if ((await readFile(filename, "utf8")).startsWith(HEADER.trimEnd())) {
			await rm(filename);
		}
	}
}
const exports = [];
const outputDeclarations = sharedBlocks
	? [
			...declarations,
			ts.factory.createTypeAliasDeclaration(
				[ts.factory.createModifier(ts.SyntaxKind.ExportKeyword)],
				BLOCK_TYPE_NAME,
				undefined,
				sharedBlocks.element,
			),
		]
	: declarations;
for (const declaration of outputDeclarations) {
	const name = declaration.name.text;
	const { text, constants, node } = transformDeclaration(declaration);
	const imports = [
		...[...constants].map(
			([constant, module]) =>
				`import { ${constant} } from "../config/${module}";`,
		),
		...referencedTypes(node).map(
			(type) => `import type { ${type} } from "./${type}";`,
		),
	];
	await writeFile(
		path.join(OUTPUT_DIRECTORY, `${name}.ts`),
		`${HEADER}${imports.join("\n")}\n\n${text}\n`,
	);
	if (PUBLIC_PAYLOAD_TYPES.has(name)) {
		exports.push(`export type { ${name} } from "./${name}";`);
	}
}

await writeFile(
	path.join(OUTPUT_DIRECTORY, "payload.d.ts"),
	`${HEADER}import type { Config } from "./Config";\n` +
		`declare module "${MODULE_NAME}" { export interface GeneratedTypes extends Config {} }\n`,
);
await writeFile(
	path.join(OUTPUT_DIRECTORY, "index.ts"),
	`${HEADER}import type {} from "./payload";\n${exports.join("\n")}\n`,
);
// Remove only the obsolete single-file output; user files are never a cleanup target.
await rm(OLD_OUTPUT, { force: true });
await rm(GENERATED_SOURCE);
